+`ssl.truststore.password` {ess-icon}::
+(<<static-cluster-setting,Static>>)
+include::{es-repo-dir}/settings/common-defs.asciidoc[tag=ssl-truststore-password]
+// end::jwt-ssl-truststore-password-tag[]
